style.css:
/* Midnight Neon — Global Style */
/* i really want this to be global */

:root {
  /* swap these colors whenever you like */
  --my-bg: #100b1c;
  --my-surface: #1b1230;
  --my-accent: #c084fc;
  --my-pink: #ff70cf;
  --my-text: #eee6ff;
}

/* dark dreamy background */
body {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* glowing headings */
h1, h2, h3 {
  color: var(--my-accent) !important;
  text-shadow: 0 0 12px #c084fc66 !important;
}

/* pretty links */
a {
  color: var(--my-pink) !important;
  transition: 0.25s ease !important;
}

a:hover {
  color: white !important;
  text-shadow: 0 0 12px var(--my-pink) !important;
}

/* rounded images */
img {
  border-radius: 12px !important;
}

/* smoother buttons */
button {
  border-radius: 12px !important;
  transition: 0.25s ease !important;
}

button:hover {
  box-shadow: 0 0 15px #c084fc88 !important;
}

/* smoother text selection */
::selection {
  background: var(--my-accent) !important;
  color: #100b1c !important;
}
